refentry.refsect1:
&reftitle.changelog;







     &Version;
     &Description;





     8.5.0
     non-array value (&null; बाहेक) destructuring गर्दा अब E_WARNING emit हुन्छ।



     7.3.0
     array destructuring मा reference assignments को लागि समर्थन थपियो।



     7.1.0
     अब list मा keys निर्दिष्ट गर्न सम्भव छ। यसले non-integer वा non-sequential keys भएका arrays को destructuring गर्न सक्षम बनाउँछ।

  &reftitle.examples;



    list का उदाहरणहरू


<?php

$info = array('coffee', 'brown', 'caffeine');

// Listing all the variables
list($drink, $color, $power) = $info;
echo "$drink is $color and $power makes it special.\n";

// Listing some of them
list($drink, , $power) = $info;
echo "$drink has $power.\n";

// Or let's skip to only the third one
list( , , $power) = $info;
echo "I need $power!\n";

// list() doesn't work with strings
list($bar) = "abcde";
var_dump($bar); // NULL
?>







    list प्रयोगको एउटा उदाहरण


<?php
$result = $pdo->query("SELECT id, name FROM employees");
while (list($id, $name) = $result->fetch(PDO::FETCH_NUM)) {
    echo "id: $id, name: $name\n";
}
?>







    nested list को प्रयोग


<?php

list($a, list($b, $c)) = array(1, array(2, 3));

var_dump($a, $b, $c);

?>


    &example.outputs;


int(1)
int(2)
int(3)





list द्वारा प्रयोग गरिने array का indices कुन क्रममा define गरिएका छन् भन्ने कुराले कुनै फरक पार्दैन।



    list र index definition को क्रम


<?php
$foo = array(2 => 'a', 'foo' => 'b', 0 => 'c');
$foo[1] = 'd';
list($x, $y, $z) = $foo;
var_dump($foo, $x, $y, $z);



यसले निम्न output दिन्छ (list syntax मा ती कुन क्रममा लेखिएका थिए भन्ने तुलनामा elements को क्रमलाई ध्यान दिनुहोस्):


array(4) {
  [2]=>
  string(1) "a"
  ["foo"]=>
  string(1) "b"
  [0]=>
  string(1) "c"
  [1]=>
  string(1) "d"
}
string(1) "c"
string(1) "d"
string(1) "a"







    keys सहितको list
    PHP 7.1.0 देखि list मा अब explicit keys पनि समावेश गर्न सकिन्छ, जसलाई arbitrary expression का रूपमा दिन सकिन्छ। integer र string keys मिसाउन अनुमति छ; यद्यपि, keys भएका र नभएका elements लाई मिसाउन सकिँदैन।


<?php
$data = [
    ["id" => 1, "name" => 'Tom'],
    ["id" => 2, "name" => 'Fred'],
];
foreach ($data as ["id" => $id, "name" => $name]) {
    echo "id: $id, name: $name\n";
}
echo PHP_EOL;
list(1 => $second, 3 => $fourth) = [1, 2, 3, 4];
echo "$second, $fourth\n";


    &example.outputs;


id: 1, name: Tom
id: 2, name: Fred

2, 4
